package com.bilalcollection.app;

import android.app.*;
import android.os.Bundle;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import android.database.*;
import android.database.sqlite.*;
import android.content.*;
import android.net.Uri;
import android.widget.ImageView;
import java.util.*;

public class MainActivity extends Activity {
  DB db; LinearLayout root, body; int brown=0xFF68423E; String page="Home"; String supplierPhoto="", designPhoto=""; ImageView supplierPreview, designPreview;
  public void onCreate(Bundle b){super.onCreate(b);db=new DB(this);show();}
  void choosePhoto(boolean supplier){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("image/*");startActivityForResult(i,supplier?101:102);}
  @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));}catch(Exception ignored){}if(requestCode==101){supplierPhoto=u.toString();if(supplierPreview!=null){supplierPreview.setImageURI(u);supplierPreview.setVisibility(View.VISIBLE);}}else if(requestCode==102){designPhoto=u.toString();if(designPreview!=null){designPreview.setImageURI(u);designPreview.setVisibility(View.VISIBLE);}}}}
  ImageView preview(){ImageView v=new ImageView(this);v.setAdjustViewBounds(true);v.setMaxHeight(260);v.setScaleType(ImageView.ScaleType.CENTER_INSIDE);v.setVisibility(View.GONE);return v;}
  void showPhoto(String uri){if(uri==null||uri.length()==0)return;try{ImageView im=new ImageView(this);im.setImageURI(Uri.parse(uri));im.setAdjustViewBounds(true);im.setMaxHeight(240);im.setScaleType(ImageView.ScaleType.CENTER_INSIDE);add(im);}catch(Exception ignored){}}
  TextView text(String s,int size,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(0xFF292321);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(4,8,4,8);return t;}
  EditText field(String hint){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);e.setTextSize(15);return e;}
  Button btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(brown));b.setTextColor(-1);b.setOnClickListener(v->r.run());return b;}
  void add(View v){body.addView(v,new LinearLayout.LayoutParams(-1,-2));}
  void show(){
    root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,14,16,14);root.setBackgroundColor(0xFFF8F5F1);
    TextView title=text("BILAL COLLECTION",25,true);title.setTextColor(0xFF4B302B);root.addView(title);
    root.addView(text("Women's Clothing • Stock & Supplier Register",13,false));
    HorizontalScrollView hsv=new HorizontalScrollView(this);LinearLayout nav=new LinearLayout(this);
    for(String p:new String[]{"Home","Designs","Suppliers","New Maal","Sale","Reports"}){Button b=new Button(this);b.setText(p);b.setAllCaps(false);b.setTextSize(12);b.setOnClickListener(v->{page=p;show();});nav.addView(b);}hsv.addView(nav);root.addView(hsv);
    ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(0,10,0,10);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
    switch(page){case "Home":home();break;case "Designs":designs();break;case "Suppliers":suppliers();break;case "New Maal":purchase();break;case "Sale":sale();break;case "Reports":reports();break;}
  }
  void home(){
    Cursor c=db.getReadableDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(received),0),COALESCE(SUM(sold),0) FROM designs",null);c.moveToFirst();int d=c.getInt(0),in=c.getInt(1),sold=c.getInt(2);c.close();int left=db.scalar("SELECT COALESCE(SUM(qty),0) FROM stock");
    add(text("Shop Overview",20,true));add(text("Total designs: "+d+"\nTotal pieces received: "+in+"\nTotal pieces sold: "+sold+"\nRemaining stock: "+left,17,false));
    add(text("Recent design stock",18,true));Cursor x=db.getReadableDatabase().rawQuery("SELECT d.name, s.name, d.received,d.sold,COALESCE((SELECT SUM(qty) FROM stock WHERE design_id=d.id),0) FROM designs d LEFT JOIN suppliers s ON s.id=d.supplier_id ORDER BY d.id DESC",null);while(x.moveToNext())add(text(x.getString(0)+"\nSupplier: "+x.getString(1)+"\nReceived "+x.getInt(2)+" • Sold "+x.getInt(3)+" • Left "+x.getInt(4),15,false));x.close();
  }
  void designs(){supplierPhoto="";designPhoto="";add(text("Add Clothing Design",20,true));EditText name=field("Design name");EditText code=field("Design code (optional)");EditText cat=field("Category e.g. Kurti / Suit / Dress");EditText cost=field("Purchase price per piece ₹");EditText price=field("Selling price per piece ₹");EditText sizes=field("Sizes e.g. S,M,L,XL");EditText colors=field("Colours e.g. Black,Red,Blue");Spinner sp=supplierSpinner();for(EditText e:new EditText[]{name,code,cat,cost,price,sizes,colors})add(e);add(text("Supplier linked to this design",14,true));add(sp);add(text("Design ki photo",14,true));designPreview=preview();add(designPreview);add(btn("Choose Design Photo",()->choosePhoto(false)));add(btn("Save Design",()->{if(name.getText().length()==0||sp.getSelectedItemPosition()<0){msg("Design aur supplier select karein.");return;}try{db.getWritableDatabase().execSQL("INSERT INTO designs(name,code,category,supplier_id,cost,price,sizes,colors,received,sold,image_uri) VALUES(?,?,?,?,?,?,?,?,0,0,?)",new Object[]{name.getText().toString(),code.getText().toString(),cat.getText().toString(),selectedId(sp),Double.parseDouble(cost.getText().toString()),Double.parseDouble(price.getText().toString()),sizes.getText().toString(),colors.getText().toString(),designPhoto});msg("Design saved with photo.");show();}catch(Exception ex){msg("Price fields check karein.");}}));add(text("Saved Designs",18,true));Cursor c=db.getReadableDatabase().rawQuery("SELECT d.name,s.name,d.code,d.price,d.received,d.sold,COALESCE((SELECT SUM(qty) FROM stock WHERE design_id=d.id),0),d.image_uri FROM designs d LEFT JOIN suppliers s ON s.id=d.supplier_id",null);while(c.moveToNext()){showPhoto(c.getString(7));add(text(c.getString(0)+" ("+c.getString(2)+")\nSupplier: "+c.getString(1)+"\nPrice ₹"+c.getDouble(3)+" • Received "+c.getInt(4)+" • Sold "+c.getInt(5)+" • Left "+c.getInt(6),15,false));}c.close();}
  Spinner supplierSpinner(){Spinner s=new Spinner(this);Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM suppliers ORDER BY name",null);ArrayList<String> names=new ArrayList<>();ArrayList<Integer> ids=new ArrayList<>();while(c.moveToNext()){ids.add(c.getInt(0));names.add(c.getString(1));}c.close();ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);s.setAdapter(a);s.setTag(ids);return s;}
  int selectedId(Spinner s){ArrayList<Integer> ids=(ArrayList<Integer>)s.getTag();return ids==null||s.getSelectedItemPosition()<0?-1:ids.get(s.getSelectedItemPosition());}
  void suppliers(){supplierPhoto="";add(text("Add Supplier",20,true));EditText n=field("Supplier / shop name"),ph=field("Mobile number"),ad=field("Address / market");add(n);add(ph);add(ad);add(text("Supplier ki photo",14,true));supplierPreview=preview();add(supplierPreview);add(btn("Choose Supplier Photo",()->choosePhoto(true)));add(btn("Save Supplier",()->{if(n.getText().length()==0){msg("Supplier name likhein.");return;}db.getWritableDatabase().execSQL("INSERT INTO suppliers(name,phone,address,image_uri) VALUES(?,?,?,?)",new Object[]{n.getText().toString(),ph.getText().toString(),ad.getText().toString(),supplierPhoto});msg("Supplier saved.");show();}));add(text("Supplier-wise designs and stock",18,true));Cursor c=db.getReadableDatabase().rawQuery("SELECT s.name,s.phone,d.name,d.received,d.sold,COALESCE((SELECT SUM(qty) FROM stock WHERE design_id=d.id),0),s.image_uri FROM suppliers s LEFT JOIN designs d ON d.supplier_id=s.id ORDER BY s.name",null);while(c.moveToNext()){showPhoto(c.getString(6));add(text(c.getString(0)+" • "+c.getString(1)+"\nDesign: "+(c.isNull(2)?"No design linked":c.getString(2))+"\nReceived "+c.getInt(3)+" • Sold "+c.getInt(4)+" • Remaining "+c.getInt(5),15,false));}c.close();}
  Spinner designSpinner(){Spinner s=new Spinner(this);Cursor c=db.getReadableDatabase().rawQuery("SELECT id,name FROM designs ORDER BY name",null);ArrayList<String> names=new ArrayList<>();ArrayList<Integer> ids=new ArrayList<>();while(c.moveToNext()){ids.add(c.getInt(0));names.add(c.getString(1));}c.close();s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));s.setTag(ids);return s;}
  void purchase(){add(text("Receive New Maal",20,true));Spinner d=designSpinner();add(text("Select design",14,true));add(d);EditText size=field("Size (e.g. M)"),color=field("Colour (e.g. Black)"),qty=field("Pieces received"),cost=field("Purchase price per piece ₹");add(size);add(color);add(qty);add(cost);add(btn("Save Purchase & Add Stock",()->{int id=selectedId(d);try{int q=Integer.parseInt(qty.getText().toString());if(id<0||q<1||size.getText().length()==0||color.getText().length()==0)throw new Exception();String k=size.getText()+"|"+color.getText();Cursor existing=db.getReadableDatabase().rawQuery("SELECT qty FROM stock WHERE design_id=? AND variant=?",new String[]{""+id,k});boolean found=existing.moveToFirst();int old=found?existing.getInt(0):0;existing.close();if(found)db.getWritableDatabase().execSQL("UPDATE stock SET qty=qty+? WHERE design_id=? AND variant=?",new Object[]{q,id,k});else db.getWritableDatabase().execSQL("INSERT INTO stock(design_id,variant,qty) VALUES(?,?,?)",new Object[]{id,k,q});db.getWritableDatabase().execSQL("UPDATE designs SET received=received+?,cost=? WHERE id=?",new Object[]{q,Double.parseDouble(cost.getText().toString()),id});db.getWritableDatabase().execSQL("INSERT INTO purchases(design_id,variant,qty,cost,date) VALUES(?,?,?,?,datetime('now','localtime'))",new Object[]{id,k,q,Double.parseDouble(cost.getText().toString())});msg("Stock updated.");show();}catch(Exception ex){msg("Design, size, colour, quantity aur cost check karein.");}}));}
  void sale(){add(text("Record Sale",20,true));Spinner d=designSpinner();add(text("Select design",14,true));add(d);EditText size=field("Size"),color=field("Colour"),qty=field("Pieces sold"),price=field("Sale price per piece ₹"),customer=field("Customer name (optional)");for(EditText e:new EditText[]{size,color,qty,price,customer})add(e);add(btn("Record Sale & Reduce Stock",()->{int id=selectedId(d);try{int q=Integer.parseInt(qty.getText().toString());String key=size.getText()+"|"+color.getText();Cursor c=db.getReadableDatabase().rawQuery("SELECT qty FROM stock WHERE design_id=? AND variant=?",new String[]{""+id,key});int have=c.moveToFirst()?c.getInt(0):0;c.close();if(id<0||q<1||q>have)throw new Exception("Not enough stock. Available: "+have);double p=Double.parseDouble(price.getText().toString());db.getWritableDatabase().execSQL("UPDATE stock SET qty=qty-? WHERE design_id=? AND variant=?",new Object[]{q,id,key});db.getWritableDatabase().execSQL("UPDATE designs SET sold=sold+? WHERE id=?",new Object[]{q,id});db.getWritableDatabase().execSQL("INSERT INTO sales(design_id,variant,qty,price,customer,date) VALUES(?,?,?,?,?,datetime('now','localtime'))",new Object[]{id,key,q,p,customer.getText().toString()});msg("Sale saved. Stock reduced.");show();}catch(Exception ex){msg(ex.getMessage()==null?"Sale details check karein.":ex.getMessage());}}));}
  void reports(){add(text("Sales & Stock Report",20,true));Cursor c=db.getReadableDatabase().rawQuery("SELECT COALESCE(SUM(qty*price),0),COALESCE(SUM(qty),0) FROM sales",null);c.moveToFirst();add(text("Total sales value: ₹"+c.getDouble(0)+"\nTotal pieces sold: "+c.getInt(1),17,false));c.close();add(text("Variant-wise remaining stock",18,true));Cursor x=db.getReadableDatabase().rawQuery("SELECT d.name,s.variant,s.qty FROM stock s JOIN designs d ON d.id=s.design_id ORDER BY d.name,s.variant",null);while(x.moveToNext())add(text(x.getString(0)+" • "+x.getString(1)+" : "+x.getInt(2)+" pieces",15,false));x.close();}
  void msg(String s){new AlertDialog.Builder(this).setTitle("Bilal Collection").setMessage(s).setPositiveButton("OK",null).show();}
  static class DB extends SQLiteOpenHelper{
    DB(Context c){super(c,"bilal_collection.db",null,2);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE suppliers(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,phone TEXT,address TEXT,image_uri TEXT)");d.execSQL("CREATE TABLE designs(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,code TEXT,category TEXT,supplier_id INTEGER,cost REAL,price REAL,sizes TEXT,colors TEXT,received INTEGER,sold INTEGER,image_uri TEXT)");d.execSQL("CREATE TABLE stock(design_id INTEGER,variant TEXT,qty INTEGER,PRIMARY KEY(design_id,variant))");d.execSQL("CREATE TABLE purchases(id INTEGER PRIMARY KEY AUTOINCREMENT,design_id INTEGER,variant TEXT,qty INTEGER,cost REAL,date TEXT)");d.execSQL("CREATE TABLE sales(id INTEGER PRIMARY KEY AUTOINCREMENT,design_id INTEGER,variant TEXT,qty INTEGER,price REAL,customer TEXT,date TEXT)");}public void onUpgrade(SQLiteDatabase d,int o,int n){if(o<2){d.execSQL("ALTER TABLE suppliers ADD COLUMN image_uri TEXT");d.execSQL("ALTER TABLE designs ADD COLUMN image_uri TEXT");}}int scalar(String q){Cursor c=getReadableDatabase().rawQuery(q,null);c.moveToFirst();int x=c.getInt(0);c.close();return x;}}
}
